import {useLayoutEffect,useRef} from 'react';
import {TextInput,View,type ViewProps} from 'react-native';
import {createStore} from 'zustand/vanilla';
import {useStore} from 'zustand';
import {Select} from '@/components/nyc-tron/ui/components/Select';
import {Button} from '@/components/nyc-tron/ui/components/Button';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';
import {joinClasses} from '@/components/nyc-tron/ui/components/styles';
import {parsePhotoPreset,serializePhotoPreset,validatePhotoPresets,type PhotoPreset} from '@/components/nyc-tron/ui/components/forge/photo/photo-presets';
export type {PhotoPreset} from '@/components/nyc-tron/ui/components/forge/photo/photo-presets';
export interface PresetManagerProps extends Omit<ViewProps,'children'> {
 readonly scope:string;readonly presets:readonly PhotoPreset[];readonly selectedId:string|null;readonly onSelect:(id:string)=>void;
 readonly onRename:(id:string,name:string,signal:AbortSignal)=>void|Promise<void>;
 readonly onDelete:(id:string,signal:AbortSignal)=>void|Promise<void>;
 readonly onReadImport:(signal:AbortSignal)=>string|Promise<string>;
 readonly onImport:(preset:PhotoPreset,signal:AbortSignal)=>void|Promise<void>;
 readonly onExport:(payload:string,signal:AbortSignal)=>void|Promise<void>;
 readonly disabled?:boolean;readonly unstyled?:boolean;
}
const makeStore=()=>createStore(()=>({name:null as string|null}));
/** Versioned preset transfer with validation before any host write, plus rename/delete. */
export function PresetManager({scope,presets,selectedId,onSelect,onRename,onDelete,onReadImport,onImport,onExport,disabled=false,unstyled=false,...props}:PresetManagerProps){
 validatePhotoPresets(presets);if(!scope.trim())throw new TypeError('Preset library requires a scope');
 const action=useOwnedAction(scope),locked=disabled||action.pending!==null,selected=presets.find(p=>p.id===selectedId);
 const local=useRef<ReturnType<typeof makeStore>|null>(null);local.current??=makeStore();const store=local.current,s=useStore(store,s=>s);
 useLayoutEffect(()=>{store.setState({name:null});},[scope,selectedId,store]);
 const name=s.name??selected?.name??'';
 return <View {...props} style={[{gap:8},props.style]}>
  <Select label="Managed photo preset" value={selectedId??''} options={presets.map(p=>({value:p.id,label:p.name}))} placeholder="Select a photo preset" disabled={locked} unstyled={unstyled} onValueChange={id=>{if(!locked)onSelect(id);}}/>
  <TextInput accessibilityLabel="Photo preset name" value={name} maxLength={256} editable={!locked&&!!selected} aria-disabled={locked||!selected} onChangeText={name=>store.setState({name})} style={{minHeight:44,padding:8}} {...{className:joinClasses(!unstyled&&'text-text border border-border rounded-control')}}/>
  <Button title="Rename photo preset" disabled={locked||!selected||!name.trim()||name===selected.name} unstyled={unstyled} onPress={()=>{if(!locked&&selected&&name.trim())void action.run('rename',signal=>onRename(selected.id,name.trim(),signal));}}/>
  <Button title="Delete photo preset" disabled={locked||!selected} unstyled={unstyled} onPress={()=>{if(!locked&&selected)void action.run('delete',signal=>onDelete(selected.id,signal));}}/>
  <Button title="Import photo preset" disabled={locked} unstyled={unstyled} onPress={()=>{if(locked)return;void action.run('import',async signal=>{const preset=parsePhotoPreset(await onReadImport(signal));if(signal.aborted)return;if(presets.some(p=>p.id===preset.id))throw new Error('A preset with this identity already exists');await onImport(preset,signal);});}}/>
  <Button title="Export photo preset" disabled={locked||!selected} unstyled={unstyled} onPress={()=>{if(!locked&&selected)void action.run('export',signal=>onExport(serializePhotoPreset(selected),signal));}}/>
  {action.pending!==null?<Button title="Cancel preset transfer" unstyled={unstyled} onPress={action.cancel}/>:null}
  <ErrorMessage {...(action.error?{message:action.error}:{})} unstyled={unstyled}/>
 </View>;
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
